        address target,
        bytes[] memory targetQueryCalldata,
        address factory,
        bytes memory factoryCalldata
    ) {
        assembly {
            // If the target does not have code, deploy it using the factory.
            if iszero(extcodesize(target)) {
                // Perform the factory deployment call.
                let success := call(gas(), factory, 0, add(factoryCalldata, 0x20), mload(factoryCalldata), 0, 0)
                // If the factory call reverted, revert.
                if iszero(success) {
                    // Copy the revert data.
                    returndatacopy(0x00, 0x00, returdatasize())
                    // Revert with the return data.
                    revert(0x00, returdatasize())
                }
                // Copy the return data (the address of the deployed contract).
                returndatacopy(0x00, 0x00, returdatasize())
                // The return data is expected to be the address (32 bytes, left-padded).
                let deployed := mload(0x00)
                // Verify that the deployed address matches the expected target.
                if iszero(eq(deployed, target)) {
                    mstore(0x00, 0x96236804) // `ReturnedAddressMismatch()`.
                    revert(0x1c, 0x04)
                }
            }

            // The memory layout for the results:
            // 0x00..0x20: result offset (dynamic pointer)
            // 0x20..0x40: result array length
            // 0x40..0x60..: result array elements (offsets for each bytes)
            // After the offsets, the actual bytes data follows.

            let numQueries := mload(targetQueryCalldata)

            // We will write the result offsets starting at position 0x40.
            // Position 0x00 will hold the offset to the array.
            // Position 0x20 will hold the array length.

            // Store the offset to the result array (always 0x20 since offset starts at 0x20).
            mstore(0x00, 0x20)
            // Store the number of results.
            mstore(0x20, numQueries)

            // The pointer for writing offsets of each element in the result array.
            let offsetPtr := 0x40
            // The pointer for writing the actual data of each result.
            // We need to leave space for all the offsets (numQueries * 0x20).
            let dataPtr := add(0x40, shl(5, numQueries))

            // Iterate over each query calldata.
            for { let i := 0 } lt(i, numQueries) { i := add(i, 1) } {
                // Get the calldata bytes for this query.
                let calldataPtr := add(targetQueryCalldata, add(0x20, shl(5, i)))
                let calldataBytes := mload(calldataPtr)
                let calldataOffset := add(calldataPtr, 0x20)

                // Write the offset for this result element.
                // The offset is relative to the start of the array (position 0x40).
                mstore(offsetPtr, sub(dataPtr, 0x40))
                offsetPtr := add(offsetPtr, 0x20)

